const {Resolver} = require('@parcel/plugin');
const path = require('path');

module.exports = new Resolver({
  resolve({specifier, options}) {
    // Absolute URLs refer to pages generated by Eleventy in _site, except for
    // /assets and /plugin-browser, which are aliased to src in package.json.
    if (
      specifier.startsWith('/') &&
      !specifier.startsWith('/assets/') &&
      !specifier.startsWith('/plugin-browser/')
    ) {
      return {
        filePath: path.join(options.projectRoot, '_site', specifier)
      };
    }

    return null;
  }
});
